import React, { useEffect, useState } from "react";
import axios from "axios";
import AppShell from "./ui/AppShell";
import Panel from "./ui/Panel";
import StatCard from "./ui/StatCard";
import AlertBox from "./AlertBox";
import { FaClipboardList, FaPlusCircle, FaUsers } from "react-icons/fa";
import "./theme.css";

function AssignmentsTeacher() {
  const teacherId = localStorage.getItem("user_id");

  const [courses, setCourses] = useState([]);
  const [assignments, setAssignments] = useState([]);
  const [selectedCourseId, setSelectedCourseId] = useState("");
  const [selectedSubjectCode, setSelectedSubjectCode] = useState("");
  const [alert, setAlert] = useState(null);

  const [form, setForm] = useState({
    title: "",
    description: "",
    due_date: ""
  });

  useEffect(() => {
    loadCourses();
  }, []);

  const loadCourses = async () => {
    try {
      const res = await axios.get("http://127.0.0.1:8000/courses");
      const all = res.data.courses || [];
      const myCourses = all.filter(
        (c) => String(c.teacher_id) === String(teacherId)
      );
      setCourses(myCourses);
    } catch (err) {
      console.error(err);
    }
  };

  const loadAssignments = async (subjectCode) => {
    if (!subjectCode) {
      setAssignments([]);
      return;
    }

    try {
      const res = await axios.get(
        `http://127.0.0.1:8000/assignments/${subjectCode}`
      );
      setAssignments(res.data.assignments || []);
    } catch (err) {
      console.error(err);
      setAssignments([]);
    }
  };

  const handleCourseChange = (e) => {
    const courseId = e.target.value;
    setSelectedCourseId(courseId);

    const selectedCourse = courses.find(
      (c) => String(c.id) === String(courseId)
    );

    const subjectCode = selectedCourse?.subject_code || "";
    setSelectedSubjectCode(subjectCode);
    loadAssignments(subjectCode);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!selectedSubjectCode) {
      setAlert({
        message: "Please select course first",
        type: "error"
      });
      return;
    }

    try {
      const payload = {
        subject_code: selectedSubjectCode,
        teacher_id: Number(teacherId),
        title: form.title,
        description: form.description,
        due_date: form.due_date
      };

      const res = await axios.post(
        "http://127.0.0.1:8000/create-assignment",
        payload
      );

      setAlert({
        message: res.data.message,
        type: "success"
      });

      setForm({
        title: "",
        description: "",
        due_date: ""
      });

      loadAssignments(selectedSubjectCode);
    } catch (err) {
      console.error("ERROR FULL:", err.response?.data);
      console.error("DETAIL:", err.response?.data?.detail);

      setAlert({
        message: "Assignment creation failed",
        type: "error"
      });
    }
  };

  return (
    <AppShell
      title="Assignments Panel"
      subtitle="Create subject-wise assignments and view them instantly."
    >
      {alert && (
        <AlertBox
          message={alert.message}
          type={alert.type}
          onClose={() => setAlert(null)}
        />
      )}

      <div className="page-grid-3" style={{ marginBottom: "20px" }}>
        <StatCard
          icon={<FaClipboardList />}
          label="Assignments"
          value={assignments.length}
          hint="Assignments in selected subject"
        />
        <StatCard
          icon={<FaUsers />}
          label="Subject Code"
          value={selectedSubjectCode || "N/A"}
          hint="Currently selected subject"
        />
        <StatCard
          icon={<FaPlusCircle />}
          label="Teacher Mode"
          value="Active"
          hint="Assignment creation enabled"
        />
      </div>

      <div className="page-grid-2">
        <Panel title="Create Assignment">
          <form onSubmit={handleSubmit}>
            <select
              className="select"
              value={selectedCourseId}
              onChange={handleCourseChange}
            >
              <option value="">Select Course</option>
              {courses.map((c) => (
                <option key={c.id} value={c.id}>
                  {c.title} ({c.subject_code})
                </option>
              ))}
            </select>

            <input
              className="input"
              placeholder="Assignment Title"
              value={form.title}
              onChange={(e) => setForm({ ...form, title: e.target.value })}
            />

            <textarea
              className="textarea"
              placeholder="Question / Description"
              value={form.description}
              onChange={(e) =>
                setForm({ ...form, description: e.target.value })
              }
            />

            <input
              className="input"
              type="date"
              value={form.due_date}
              onChange={(e) => setForm({ ...form, due_date: e.target.value })}
            />

            <button className="btn btn-primary" type="submit">
              Create Assignment
            </button>
          </form>
        </Panel>

        <Panel title="Assignments List">
          {!selectedSubjectCode ? (
            <p className="muted">Select a course to view assignments.</p>
          ) : assignments.length === 0 ? (
            <p className="muted">No assignments found for this subject.</p>
          ) : (
            assignments.map((a) => (
              <div className="list-card" key={a.id}>
                <h4 style={{ marginTop: 0 }}>{a.title}</h4>
                <div className="muted">{a.description}</div>
                <div className="muted" style={{ marginTop: "8px" }}>
                  Subject Code: {a.subject_code}
                </div>
                <div className="muted" style={{ marginTop: "6px" }}>
                  Due: {a.due_date}
                </div>
              </div>
            ))
          )}
        </Panel>
      </div>
    </AppShell>
  );
}

export default AssignmentsTeacher;
